import os
from dotenv import load_dotenv

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
load_dotenv(os.path.join(BASE_DIR, '.env'))


class Config:
    SECRET_KEY = os.getenv('SECRET_KEY', 'dev-secret-key')
    SQLALCHEMY_TRACK_MODIFICATIONS = False
    SQLALCHEMY_DATABASE_URI = os.getenv(
        'DATABASE_URL',
        'sqlite:///' + os.path.join(BASE_DIR, 'data.db')
    )


class DevelopmentConfig(Config):
    DEBUG = True
    ENV = 'development'


class ProductionConfig(Config):
    DEBUG = False
    ENV = 'production'


class TestingConfig(Config):
    TESTING = True
    SQLALCHEMY_DATABASE_URI = 'sqlite:///:memory:'


config_by_name = {
    'development': DevelopmentConfig,
    'production': ProductionConfig,
    'testing': TestingConfig,
    'default': DevelopmentConfig
}


def get_configuration():
    env = os.getenv('FLASK_ENV', 'development')
    return config_by_name.get(env, DevelopmentConfig)

from flask import Blueprint, request, jsonify
from app.models.blog_post import BlogPost
from app import db
from app.utils.image_upload import upload_image

blog_posts_bp = Blueprint('blog_posts', __name__)

@blog_posts_bp.route('/blog_posts', methods=['GET'])
def get_blog_posts():
    posts = BlogPost.query.all()
    return jsonify([post.to_dict() for post in posts])

@blog_posts_bp.route('/blog_posts', methods=['POST'])
def create_blog_post():
    data = request.form
    image = request.files.get('image')
    image_url = None

    if image:
        try:
            image_url = upload_image(image)
        except ValueError as e:
            return jsonify({'error': str(e)}), 400

    new_post = BlogPost(
        title=data['title'],
        description=data['description'],
        image_url=image_url
    )
    db.session.add(new_post)
    db.session.commit()
    return jsonify(new_post.to_dict()), 201

@blog_posts_bp.route('/blog_posts/<int:id>', methods=['PUT'])
def update_blog_post(id):
    data = request.get_json()
    post = BlogPost.query.get_or_404(id)
    post.title = data['title']
    post.description = data['description']
    post.image_url = data.get('image_url')
    db.session.commit()
    return jsonify(post.to_dict())

@blog_posts_bp.route('/blog_posts/<int:id>', methods=['DELETE'])
def delete_blog_post(id):
    post = BlogPost.query.get_or_404(id)
    db.session.delete(post)
    db.session.commit()
    return '', 204

from flask import Blueprint, request, jsonify
from app.models.comment import Comment
from app import db

comments_bp = Blueprint('comments', __name__)

@comments_bp.route('/comments/<int:post_id>', methods=['GET'])
def get_comments(post_id):
    comments = Comment.query.filter_by(post_id=post_id).all()
    return jsonify([comment.to_dict() for comment in comments])

@comments_bp.route('/comments', methods=['POST'])
def add_comment():
    data = request.get_json()
    new_comment = Comment(
        post_id=data['post_id'],
        content=data['content']
    )
    db.session.add(new_comment)
    db.session.commit()
    return jsonify(new_comment.to_dict()), 201

import os
from werkzeug.utils import secure_filename

UPLOAD_FOLDER = 'app/static/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def upload_image(file):
    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file_path = os.path.join(UPLOAD_FOLDER, filename)
        file.save(file_path)
        return f'/static/uploads/{filename}'
    else:
        raise ValueError("File type is not allowed")
